const canRequestEmailOtp = (): boolean => {
  return isValidEmail(email) && !isRequestedOTP && !isSendingOtp && !isLoggingIn;
};

const canSubmitEmailOtp = (): boolean => {
  return (
    isValidEmail(email) &&
    otpCode.length === OTP_LENGTH &&
    isAcceptTNC &&
    isAcceptInfoCollection &&
    !isLoggingIn &&
    !isSendingOtp
  );
};

const handleEmailChange = (text: string): void => {
  setEmail(text);
