const handleOtpChange = (text: string): void => {
  const digits = `${text}`.replace(/\D/g, '').slice(0, OTP_LENGTH);
  setOtpCode(digits);
  setErrorLoginMessage('');
  setIsSuccessLoggedIn(false);
};

const handleGetEmailOtp = async (): Promise<void> => {
  if (!canRequestEmailOtp()) {
    if (!isValidEmail(email)) {
      setErrorLoginMessage($i18n.t('validations.invalid_email'));
    }
    return;
  }

  try {
    setIsSendingOtp(true);
    const getOTPPayload = {
      contact: email.trim(),
      lang: language || 'en',
      verifyExistingContact: false,
      source: 'circle',
      emailNotification: true,
    };
    const response = await api.sendotp(getOTPPayload);
    console.log('login-screen sendotp response=', response);
    if (response && response.success) {
      setIsGetOTP(true);
      setIsRequestedOTP(true);
      setErrorLoginMessage('');
    } else {
      setErrorLoginMessage(getSendOtpErrorMessage(response));
    }
  } catch (error) {
    setErrorLoginMessage(getSendOtpErrorMessage(error));
  } finally {
    setIsSendingOtp(false);
  }
};

const handleEmailOtpLogin = async (): Promise<void> => {
  if (!canSubmitEmailOtp()) {
    return;
  }

  try {
    setIsLoggingIn(true);
    const loginOTPPayload = {
      grant_type: 'access_token',
      contact: email.trim(),
      otp: otpCode,
    };
    const response: LoginRes | { error: { message: string } } = await api.loginOtp(loginOTPPayload);
    console.log('login-screen loginOtp response=', response);
    setIsLoggingIn(false);
    if (('success' in response) && response?.success && response?.data?.accessToken !== '' && response?.data?.circle.hasSettledPlanPurchase) {
      setEmail('');
      setOtpCode('');
      const fcmToken = await AsyncStorage.getItem('fcmToken');
      console.log('login-screen fcmToken=', fcmToken);
      if (fcmToken) {
        const fmcTokenRequest = {
          "fcmToken": fcmToken,
          "memberId": response?.data.entity.id,
          "appname": "heals"
        } as FCMTokenStoreRequestDTO;
        await $api.storeFCM(fmcTokenRequest);
      }
      $NavigationActions.reset(
        [{
          'name': $routeNames.mainTabNavigator
        }], 0
      );
    } else {
      ('success' in response) && setIsSuccessLoggedIn(response.success);
      if (('data' in response) && !response?.data?.circle.hasSettledPlanPurchase) {
        try {
          await AsyncStorage.setItem('memberData', JSON.stringify(response?.data));
          const res: MemberPolicies | undefined = await $api.member_policies()
          if (res?.policies.length === 0) {
            await AsyncStorage.clear();
            $NavigationActions.navigate(
              $routeNames.CirclePlanScreen, {
                loginData: response.data
              }
            );
          } else {
            const API_GET_LINKTOP_HEALTH_DATAAPI_GET_LINKTOP_HEALTH_DATA = getGlobalAppState();
            API_GET_LINKTOP_HEALTH_DATAAPI_GET_LINKTOP_HEALTH_DATA?.setLoginData(response?.data);
            await AsyncStorage.setItem('memberData', JSON.stringify(response?.data));
            await Keychain.setGenericPassword('password', response?.data?.accessToken);
            $NavigationActions.reset(
              [{
                'name': $routeNames.mainTabNavigator
              }], 0
            );
          }
        } catch (e) {
        }
      } else if (('error' in response) && response?.error?.message === 'Member not exist with this contact') {
        setErrorLoginMessage($i18n.t('member_not_exist'));
      } else if (('error' in response) && response?.error?.message === 'Invalid username or password') {
        setErrorLoginMessage($i18n.t('invalid_login'));
      } else {
        ('error' in response) && setErrorLoginMessage(response?.error?.message ? response.error.message : $i18n.t('try_later'));
      }
    }
  } catch (e) {
    setIsLoggingIn(false);
    setErrorLoginMessage($i18n.t('try_later'));
  }
};

