const parseOtpErrorMessage = (message: unknown): string | null => {
  if (typeof message !== 'string' || message.trim() === '') {
    return null;
  }
  try {
    const parsed = JSON.parse(message);
    if (Array.isArray(parsed) && parsed[0]?.message) {
      return String(parsed[0].message);
    }
    if (typeof parsed === 'object' && parsed !== null && parsed.message) {
      return String(parsed.message);
    }
  } catch (e) {
  }
  return message;
};

const getSendOtpErrorMessage = (response: unknown): string => {
  if (typeof response === 'object' && response !== null) {
    const errorValue = (response as {error?: unknown}).error;
    if (Array.isArray(errorValue) && errorValue[0]?.message) {
      return parseOtpErrorMessage(errorValue[0].message) || $i18n.t('try_later');
    }
    if (typeof errorValue === 'object' && errorValue !== null) {
      const nestedMessage = parseOtpErrorMessage(
        (errorValue as {message?: unknown}).message,
      );
      if (nestedMessage) {
        return nestedMessage;
      }
      const localizeKey = (errorValue as {localize_key?: unknown}).localize_key;
      if (typeof localizeKey === 'string' && localizeKey !== '') {
        const translated = $i18n.t(localizeKey);
        if (translated && translated !== localizeKey) {
          return translated;
        }
      }
    }
  }
  return $i18n.t('try_later');
};

